import { createDecipheriv, createHash, createHmac, timingSafeEqual } from 'node:crypto';

const MAX_CLOCK_SKEW_MS = 5 * 60 * 1000;
const MAX_BODY_BYTES = 128 * 1024;
const MAX_CAPSULE_TTL_MS = 120 * 1000;
const ALGORITHM = 'aes-256-gcm';

function safeEqual(left, right) {
  const a = Buffer.from(left);
  const b = Buffer.from(right);
  return a.length === b.length && timingSafeEqual(a, b);
}

function failure(requestId, status, errorCategory, retryable = false) {
  return { status, response: { ok: false, protocolVersion: 2, requestId: typeof requestId === 'string' ? requestId : 'invalid', errorCategory, retryable } };
}

function canonicalBase64(value, bytes) {
  if (typeof value !== 'string' || !/^[A-Za-z0-9+/]+={0,2}$/.test(value)) throw new Error('reject');
  const decoded = Buffer.from(value, 'base64');
  if (!decoded.length || decoded.toString('base64') !== value || (bytes && decoded.length !== bytes)) throw new Error('reject');
  return decoded;
}

function wrappingKey(version) {
  let values;
  try { values = JSON.parse(process.env.CRAZYLOOPS_DELEGATED_WRAP_KEYS ?? ''); } catch { throw new Error('reject'); }
  if (!values || Array.isArray(values) || typeof values !== 'object') throw new Error('reject');
  const encoded = values[String(version)];
  if (typeof encoded !== 'string' || !/^[A-Za-z0-9+/]{43}=$/.test(encoded)) throw new Error('reject');
  const key = Buffer.from(encoded, 'base64');
  if (key.length !== 32 || key.toString('base64') !== encoded) throw new Error('reject');
  return key;
}

function aad(body, capsule) {
  return Buffer.from(JSON.stringify({
    namespace: 'crazyloops:delegated-credential-capsule',
    protocolVersion: body.protocolVersion,
    requestId: body.requestId,
    executionId: body.executionId,
    workflowVersionId: body.workflowVersionId,
    stepId: body.stepId,
    capabilityId: body.capabilityId,
    capabilityVersion: body.capabilityVersion,
    keyVersion: capsule.keyVersion,
    algorithm: ALGORITHM,
    expiresAt: capsule.expiresAt,
  }), 'utf8');
}

export const code = async (inputs) => {
  const event = inputs.event ?? {};
  const headers = Object.fromEntries(Object.entries(event.headers ?? {}).map(([key, value]) => [key.toLowerCase(), String(value)]));
  const rawBody = Buffer.isBuffer(event.rawBody) ? event.rawBody.toString('utf8') : typeof event.rawBody === 'string' ? event.rawBody : '';
  if (!rawBody || Buffer.byteLength(rawBody) > MAX_BODY_BYTES) return failure(null, 400, 'DELEGATED_BAD_RESPONSE');

  let body;
  try { body = JSON.parse(rawBody); } catch { return failure(null, 400, 'DELEGATED_BAD_RESPONSE'); }
  const requestId = body?.requestId;
  const timestamp = headers['x-crazyloops-timestamp'];
  const requestHeader = headers['x-crazyloops-request-id'];
  const digestHeader = headers['x-crazyloops-content-sha256'];
  const signatureHeader = headers['x-crazyloops-signature'];
  const bridgeSecret = process.env.CRAZYLOOPS_BRIDGE_SECRET ?? '';

  if (bridgeSecret.length < 32 || !timestamp || !requestHeader || !digestHeader || !signatureHeader?.startsWith('v2=')) return failure(requestId, 403, 'DELEGATED_AUTH_FAILED');
  const timestampNumber = Number(timestamp);
  if (!Number.isFinite(timestampNumber) || Math.abs(Date.now() - timestampNumber) > MAX_CLOCK_SKEW_MS) return failure(requestId, 403, 'DELEGATED_AUTH_FAILED');
  const digest = createHash('sha256').update(rawBody).digest('hex');
  if (!safeEqual(digest, digestHeader) || requestHeader !== requestId) return failure(requestId, 403, 'DELEGATED_AUTH_FAILED');
  const expected = createHmac('sha256', bridgeSecret).update(`${timestamp}.${requestId}.${digest}`).digest('hex');
  if (!safeEqual(expected, signatureHeader.slice(3))) return failure(requestId, 403, 'DELEGATED_AUTH_FAILED');

  const capsule = body?.credentialCapsule;
  const validEnvelope = body?.protocolVersion === 2 && body?.capabilityId === 'internal.credential_canary' && body?.capabilityVersion === 1 && ['TEST', 'LIVE'].includes(body?.mode) && typeof body?.executionId === 'string' && typeof body?.workflowVersionId === 'string' && typeof body?.stepId === 'string' && typeof body?.idempotencyKey === 'string' && body?.input?.operation === 'canary_digest' && capsule?.algorithm === ALGORITHM && Number.isSafeInteger(capsule?.keyVersion) && Number.isSafeInteger(capsule?.expiresAt);
  if (!validEnvelope) return failure(requestId, 400, 'DELEGATED_EXECUTION_FAILED');
  if (capsule.expiresAt <= Date.now()) return failure(requestId, 400, 'DELEGATED_CAPSULE_EXPIRED');
  if (capsule.expiresAt - Date.now() > MAX_CAPSULE_TTL_MS) return failure(requestId, 400, 'DELEGATED_CAPSULE_REJECTED');

  let plaintext;
  let key;
  try {
    key = wrappingKey(capsule.keyVersion);
    const decipher = createDecipheriv(ALGORITHM, key, canonicalBase64(capsule.nonce, 12));
    decipher.setAAD(aad(body, capsule));
    decipher.setAuthTag(canonicalBase64(capsule.authTag, 16));
    plaintext = Buffer.concat([decipher.update(canonicalBase64(capsule.ciphertext)), decipher.final()]);
    if (!plaintext.length || plaintext.length > 16 * 1024) throw new Error('reject');
    const proof = createHmac('sha256', plaintext).update(`crazyloops-canary-proof:${requestId}`).digest('hex');
    return { status: 200, response: { ok: true, protocolVersion: 2, requestId, acknowledged: true, output: { proof } } };
  } catch {
    return failure(requestId, 400, 'DELEGATED_CAPSULE_REJECTED');
  } finally {
    if (plaintext) plaintext.fill(0);
    if (key) key.fill(0);
  }
};
